name:
fun ProvideMarkdownStyling(imageSourceResolver: ImageSourceResolver, isDark: Boolean = JewelTheme.isDark, markdownStyling: MarkdownStyling = remember(JewelTheme.instanceUuid) {
            if (isDark) {
                MarkdownStyling.dark()
            } else {
                MarkdownStyling.light()
            }
        }, markdownMode: MarkdownMode = MarkdownMode.Standalone, markdownProcessor: MarkdownProcessor = remember(markdownMode) { MarkdownProcessor(markdownMode = markdownMode) }, markdownBlockRenderer: MarkdownBlockRenderer = remember(markdownStyling) {
            if (isDark) {
                MarkdownBlockRenderer.dark(markdownStyling)
            } else {
                MarkdownBlockRenderer.light(markdownStyling)
            }
        }, codeHighlighter: CodeHighlighter = remember(isDark) {
            SimpleCodeHighlighter(if (isDark) SyntaxHighlightColors.dark() else SyntaxHighlightColors.light())
        }, content: () -> Unit)

